input.new_string:
  page.addEventListener('click', function (e) {
    var btn = e.target.closest('button');
    if (!btn || !page.contains(btn)) return;
    e.preventDefault();
  }, true);

  document.documentElement.classList.add('has-khoa-detail');

  /* Mục lục: CSS sticky bị html/body overflow-x:hidden phá. Pin bằng JS khi nav bị cuốn đi. */
  (function () {
    var layout = page.querySelector('.proc-layout');
    var slot = page.querySelector('.proc-nav-slot');
    var nav = page.querySelector('.proc-nav');
    if (!layout || !slot || !nav) return;

    var mq = window.matchMedia('(min-width: 901px)');
    var pinned = false;
    var navWidth = 0;
    var ticking = false;

    function headerOffset() {
      var bar = document.querySelector('.will-sticky .sticky-active.active')
        || document.querySelector('.vs-header .header-box')
        || document.querySelector('.vs-header');
      if (!bar) return 96;
      var bottom = bar.getBoundingClientRect().bottom;
      if (bottom <= 0) return 24;
      return Math.round(bottom) + 12;
    }

    function clearPin() {
      nav.classList.remove('is-pinned', 'is-ended');
      nav.style.top = '';
      nav.style.left = '';
      nav.style.width = '';
      slot.style.minHeight = '';
      pinned = false;
    }

    function update() {
      if (!mq.matches) {
        clearPin();
        return;
      }

      var offset = headerOffset();
      page.style.setProperty('--proc-nav-top', offset + 'px');

      var layoutRect = layout.getBoundingClientRect();
      var navHeight = nav.offsetHeight;
      var start = layoutRect.top;
      var stop = layoutRect.bottom - navHeight;

      if (start >= offset) {
        clearPin();
        return;
      }

      if (!pinned) {
        navWidth = slot.getBoundingClientRect().width;
        slot.style.minHeight = navHeight + 'px';
      }

      if (stop <= offset) {
        nav.classList.remove('is-pinned');
        nav.classList.add('is-ended');
        nav.style.top = (layout.offsetHeight - navHeight) + 'px';
        nav.style.left = '0';
        nav.style.width = navWidth + 'px';
        pinned = true;
        return;
      }

      nav.classList.add('is-pinned');
      nav.classList.remove('is-ended');
      nav.style.top = offset + 'px';
      nav.style.left = layoutRect.left + 'px';
      nav.style.width = navWidth + 'px';
      pinned = true;
    }

    function onScroll() {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () {
        update();
        ticking = false;
      });
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', function () {
      pinned = false;
      navWidth = 0;
      update();
    });
    update();
  })();

