private static SessionUser RequirePermission(HttpContext context, params string[] permissions)
{
    SessionUser user = context.Session[Globals.USER] as SessionUser;
    bool allowed = false;
    if (user != null)
    {
        foreach (string permission in permissions)
        {
            if (user.IsPermission(permission))
            {
                allowed = true;
                break;
            }
        }
    }

    if (!allowed)
    {
        context.Response.StatusCode = 403;
        WriteJson(context, false, "Bạn không có quyền sử dụng chức năng này.", null);
        return null;
    }
    return user;
}

